-- Foreign keys, rules and policies, now that all the tables exist.

CREATE RULE cust_rule AS
    ON DELETE TO app.customers
   WHERE old.id < 0 DO INSTEAD NOTHING;
CREATE RULE cust_rule_dis AS
    ON UPDATE TO app.customers
   WHERE old.id < '-10'::integer DO  INSERT INTO app.audit_log (msg)
  VALUES ('updated'::text);
ALTER TABLE app.customers DISABLE RULE cust_rule_dis;
ALTER TABLE app.customers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "P Update" ON app.customers FOR UPDATE
    USING (
CASE
    WHEN (score > (5)::numeric) THEN true
    ELSE false
END);
CREATE POLICY p_all ON app.customers AS RESTRICTIVE
    USING (true)
    WITH CHECK (((email)::text <> ''::text));
CREATE POLICY p_sel ON app.customers FOR SELECT
    TO "Bob", alice
    USING ((score > (0)::numeric));

ALTER TABLE public.orders ADD CONSTRAINT orders_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES app.customers(id) ON DELETE CASCADE;
ALTER TABLE public.orders ADD CONSTRAINT orders_referrer_fk FOREIGN KEY (referrer_id) REFERENCES app.customers(id) MATCH FULL ON UPDATE SET NULL;

ALTER TABLE public.events ADD CONSTRAINT events_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES app.customers(id);

ALTER TABLE public.cache_tbl ADD CONSTRAINT cache_tbl_parent_fkey FOREIGN KEY (parent) REFERENCES cache_tbl(k);

ALTER TABLE public.secrets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.secrets FORCE ROW LEVEL SECURITY;

CREATE POLICY loose_p ON public.loose
    USING ((id > 0));

ALTER TABLE public.room_names ADD CONSTRAINT room_names_fk FOREIGN KEY (id, PERIOD valid_at) REFERENCES rooms(id, PERIOD valid_at);

ALTER TABLE public.gen_ref ADD CONSTRAINT gen_ref_fk FOREIGN KEY (a) REFERENCES app.customers(id) NOT ENFORCED;
